'use strict';
const fs=require('fs'),path=require('path'),zlib=require('zlib'),crypto=require('crypto'),assert=require('assert/strict');
const H=b=>crypto.createHash('sha256').update(b).digest('hex');
const base=path.resolve('docs/optimization-plan/evidence'), index=path.join(base,'m4-source-technical-closure-20261029.json'),raw=fs.readFileSync(index);assert.equal(H(raw),'fa14e742fbda8d09b5de541d0468480572e4cc0a85bb4f4625a25fd66422935a');const x=JSON.parse(raw),a=x.archive;
assert.equal(a.records.length,356);assert.equal(a.blobs.length,268);assert.equal(new Set(a.records.map(r=>r.file.toLowerCase())).size,356);const map=new Map();let packed=0,decoded=0;for(const b of a.blobs){assert.match(b.file,/^m4-source-technical-closure-20261029\/blobs\/[a-f0-9]{64}\.gz$/);const full=path.resolve(base,b.file);assert.ok(full.startsWith(base+path.sep));assert.ok(!map.has(b.file));const data=fs.readFileSync(full);assert.equal(data.length,b.bytes);assert.equal(H(data),b.sha256);const plain=zlib.gunzipSync(data);assert.equal(plain.length,b.decodedBytes);assert.equal(H(plain),b.decodedSha256);assert.equal(path.basename(b.file),b.decodedSha256+'.gz');packed+=data.length;decoded+=plain.length;map.set(b.file,b)}
