const expected={'FINAL-VERIFICATION.json':'dc1ad788860d9b4452e844978510b9a9f9de37003d1d7c4cf92304a55725450a','SOURCE-SET.json':'e26edb7fdb55a4fb91e1b97be2830edb323ac1f096b2e454e7780f9b97485ddf','ROOT-TOOL-TERMINAL.json':'c20df5bf755f795886d94c66296ee48b82f8f5bd0d2889aa24cfa42c08aa3520','PIN-RECHECK.json':'62e1bb26b9b4a3ce3d310461260e6d87cee5517b314754c7cc0257ea61c1df55'};for(const [name,sha] of Object.entries(expected))assert.ok(a.records.some(r=>r.archived&&r.file.toLowerCase().endsWith('\\'+name.toLowerCase())&&r.sha256===sha),name);
const v=x.verified;for(const [k,n] of Object.entries({paths:6909,uniqueObjects:6728,uniqueCanonicalBytes:153241307,logicalCanonicalBytes:157470942,containerPaths:6877,connectorPaths:28,fontPaths:4,missingPaths:0,derivedDirectories:3,canonicalTransformPaths:68,crlfPairs:5930}))assert.equal(v[k],n,k);assert.equal(x.baselineCommit,'f72f38c1933015eb4d58e0be81aeec5467beba0d');for(const k of ['runtimeSourcesComplete','binaryCorrespondence','provenanceComplete','legalAcceptance','componentExecuted','ready','wholeM4Complete','wholeRuyi31Complete'])assert.equal(x.authority[k],false,k);assert.equal(v.extracted,false);console.log(JSON.stringify({indexSha256:H(raw),references:a.records.length,archived,external,blobs:map.size,packedBytes:packed,decodedUniqueBytes:decoded,referencePathsUnique:true,blobPathsUniqueAndContained:true,noOrphans:true,keyEvidence:expected,counts:v,authority:x.authority}));
